/**
 * Embeds the schema migrations this package bundles into
 * src/migrations.generated.ts: every migrations/<number>_<mq version>.up.sql,
 * in version order. Runs on `npm ci` / `npm install` (prepare), before `tsc`
 * (npm run build) and as Jest's globalSetup. The generated file is not
 * committed.
 *
 * migrations/ is a copy of mq/migrations under numbered names, which
 * `make sync` keeps in step with it (CI checks it), so the commit that changes
 * the schema also changes this package and releases it. Do not edit it here.
 */
const fs = require('fs');
const path = require('path');

const SOURCE = path.join(__dirname, '..', 'migrations');
const TARGET = path.join(__dirname, '..', 'src', 'migrations.generated.ts');
const UP_FILE = /^(\d+)_(.+)\.up\.sql$/;

/** The bundled migrations, in version order. */
function bundledMigrations() {
  const all = fs.readdirSync(SOURCE)
    .map((file) => UP_FILE.exec(file))
    .filter((match) => match !== null)
    .map(([file, version, name]) => ({ file, version: Number(version), name }))
    .sort((a, b) => a.version - b.version);
  if (all.length === 0) {
    throw new Error(`${SOURCE} has no migrations`);
  }
  for (let i = 1; i < all.length; i++) {
    if (all[i].version === all[i - 1].version) {
      throw new Error(`two migrations numbered ${all[i].version}: ${all[i - 1].file} and ${all[i].file}`);
    }
  }
  return all;
}

function embedMigrations() {
  const entries = bundledMigrations().map(({ file, version, name }) => ({
    version,
    name,
    sql: fs.readFileSync(path.join(SOURCE, file), 'utf8'),
  }));
  const content =
    '// Generated by scripts/embed-migrations.js from migrations/. Do not edit.\n' +
    'export const MIGRATIONS: ReadonlyArray<{ readonly version: number; readonly name: string; readonly sql: string }> = ' +
    JSON.stringify(entries, null, 2) +
    ';\n';
  const current = fs.existsSync(TARGET) ? fs.readFileSync(TARGET, 'utf8') : '';
  if (current !== content) {
    fs.writeFileSync(TARGET, content);
  }
}

module.exports = embedMigrations;
module.exports.bundledMigrations = bundledMigrations;

if (require.main === module) {
  embedMigrations();
}
